CREATE TABLE borrowings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, direction text NOT NULL CHECK (direction IN ('borrowed','lent')), txn_date date NOT NULL DEFAULT current_date, counterparty text NOT NULL, item_type text NOT NULL DEFAULT 'Material', item_code text, item_name text NOT NULL, qty numeric(12,3) NOT NULL DEFAULT 0, unit_cost numeric(12,4) NOT NULL DEFAULT 0, qty_returned numeric(12,3) NOT NULL DEFAULT 0, due_date date, return_date date, settlement_status text NOT NULL DEFAULT 'Open', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())